package com.example.notification_service.entity;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity @Table(name="processed_events")public class ProcessedEvent{@Id @Column(name="event_id")private UUID eventId;@Column(name="event_type")private String eventType;@Column(name="processed_at")private Instant processedAt;protected ProcessedEvent(){}public ProcessedEvent(UUID id,String type){eventId=id;eventType=type;processedAt=Instant.now();}public UUID getEventId(){return eventId;}}
